from dataclasses import dataclass

@dataclass(frozen=True)
class Num:
    value: int

@dataclass(frozen=True)
class Add:
    left: "Expr"
    right: "Expr"

@dataclass(frozen=True)
class Mul:
    left: "Expr"
    right: "Expr"

Expr = Num | Add | Mul

def chain(n):
    e = Num(1)
    for i in range(n):
        e = Add(Num(1), e)
    return e

def count_nodes(e):
    match e:
        case Num(_):
            return 1
        case Add(left, right) | Mul(left, right):
            return 1 + count_nodes(left) + count_nodes(right)
        case _:
            raise TypeError(f"not an expression: {e!r}")
